import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    alphabet = draw(st.sampled_from(["ab", "a", "abc", "xyz"]))
    s = draw(st.text(alphabet=alphabet, min_size=1, max_size=12))
    if draw(st.booleans()):
        s = draw(st.sampled_from([s[0] * len(s), "".join(sorted(s)), "".join(sorted(s, reverse=True))]))
    c = draw(st.sampled_from(sorted(set(s))))
    return json.dumps(s) + "\n" + json.dumps(c) + "\n"

def validate(inp):
    lines = inp.split("\n")
    if len(lines) < 2:
        return False
    try:
        s = json.loads(lines[0])
        c = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(s, str) or not isinstance(c, str):
        return False
    if not (1 <= len(s) <= 10**5):
        return False
    if not all("a" <= ch <= "z" for ch in s):
        return False
    if len(c) != 1 or not ("a" <= c <= "z"):
        return False
    return True

def ref(inp):
    lines = inp.split("\n")
    s = json.loads(lines[0])
    c = json.loads(lines[1])
    n = len(s)
    count = 0
    # Brute force over all substrings s[i..j] with i <= j
    for i in range(n):
        for j in range(i, n):
            if s[i] == c and s[j] == c:
                count += 1
    return json.dumps(count)
