import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    alphabet = draw(st.sampled_from(["ab", "abc", "a", "xyz", "abcdefghijklmnopqrstuvwxyz"]))
    n = draw(st.integers(1, 12))
    s = draw(st.lists(st.sampled_from(list(alphabet)), min_size=n, max_size=n))
    s = "".join(s)
    if draw(st.booleans()):
        # edge case: all equal characters
        ch = draw(st.sampled_from(list(alphabet)))
        s = ch * n
    c = draw(st.sampled_from(sorted(set(s) | {"z"})))
    return json.dumps(s) + "\n" + json.dumps(c) + "\n"

def validate(inp):
    lines = inp.split("\n")
    lines = [l for l in lines if l != ""]
    if len(lines) != 2:
        return False
    s = json.loads(lines[0])
    c = json.loads(lines[1])
    if not isinstance(s, str) or not isinstance(c, str):
        return False
    if not (1 <= len(s) <= 10**5):
        return False
    if not all("a" <= ch <= "z" for ch in s):
        return False
    if len(c) != 1 or not ("a" <= c <= "z"):
        return False
    return True

def ref(inp):
    lines = [l for l in inp.split("\n") if l != ""]
    s = json.loads(lines[0])
    c = json.loads(lines[1])
    n = len(s)
    count = 0
    for i in range(n):
        for j in range(i, n):
            if s[i] == c and s[j] == c:
                count += 1
    return json.dumps(count)
